// Quiet, synthesized kitchen sounds. No external audio or tracking.
let context,noiseGain,muted=false;function unlock(){if(context)return;const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)return;try{context=new Audio();const buffer=context.createBuffer(1,context.sampleRate*2,context.sampleRate),data=buffer.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=(Math.random()*2-1)*.5;const source=context.createBufferSource(),filter=context.createBiquadFilter();source.buffer=buffer;source.loop=true;filter.type='highpass';filter.frequency.value=1200;noiseGain=context.createGain();noiseGain.gain.value=0;source.connect(filter).connect(noiseGain).connect(context.destination);source.start();context.resume()}catch{}}
window.addEventListener('pointerdown',unlock,{once:true});window.addEventListener('click',unlock,{once:true});window.cookAudio={fry(on){if(noiseGain)noiseGain.gain.setTargetAtTime(on&&!muted?.028:0,context.currentTime,.1)},tap(){if(!context||muted)return;const o=context.createOscillator(),g=context.createGain();o.type='triangle';o.frequency.setValueAtTime(440,context.currentTime);o.frequency.exponentialRampToValueAtTime(90,context.currentTime+.07);g.gain.setValueAtTime(.08,context.currentTime);g.gain.exponentialRampToValueAtTime(.001,context.currentTime+.09);o.connect(g).connect(context.destination);o.start();o.stop(context.currentTime+.1)}};document.querySelector('#cook-sound').onclick=()=>{unlock();muted=!muted;document.querySelector('#cook-sound').textContent=muted?'♩':'♪';document.querySelector('#cook-sound').setAttribute('aria-label',muted?'Unmute cooking sounds':'Mute cooking sounds');if(muted&&noiseGain)noiseGain.gain.value=0};document.addEventListener('visibilitychange',()=>{if(document.hidden&&noiseGain)noiseGain.gain.value=0});
